functions.jumpMap:
{
   var _loc2_;
   _loc2_ = 1;
   while(_loc2_ <= 6)
   {
      if(this["entry" + _loc2_].hitTest(this.role._x,this.role._y,false) == true && this["entry" + _loc2_]._visible == true)
      {
         this.jumpToMap(this["entry" + _loc2_]);
         return true;
      }
      _loc2_ = _loc2_ + 1;
   }
   return false;
}

functions.jumpToMap:
{
   if(entry._alpha == 0)
   {
      return false;
   }
   entry1._visible = true;
   entry2._visible = true;
   entry3._visible = true;
   entry4._visible = true;
   entry5._visible = true;
   entry6._visible = true;
   switch(entry.toMap)
   {
      case "沼泽郊区":
         if(_parent.task.getTask("接应国王").isComplete != true)
         {
            _global.msg.open("\r\r\r前方有魔族军团，没有国王命令不能进入");
            return false;
         }
         break;
      case "冰封走廊":
         if(role.levels < 70)
         {
            _global.msg.open("\r\r\r前方有魔族军团，70级前不能进入");
            return false;
         }
         break;
      case "失落高地一":
         if(role.levels < 100)
         {
            _global.msg.open("\r\r\r100级前不能进入");
            return false;
         }
   }
   if(entry)
   {
      this.nextMap = entry.toMap;
      this.nextEntry = entry.toEntry;
      this.role.myTarget = undefined;
      this.huanShou1.myTarget = undefined;
      this.huanShou2.myTarget = undefined;
      this.huanShou3.myTarget = undefined;
      this.gotoAndStop(this.nextMap);
      return true;
   }
   return false;
}

functions.allowJumpMap:
{
   if(this.nextMap == toMap)
   {
      this.goods.clearGoods();
      this._parent.closeAllPanel();
      this._parent.warning.close();
      this.nowMap = this.nextMap;
      this.afterJumpMap(this.nowMap);
      return true;
   }
   this.nextMap = this.nowMap;
   this.gotoAndStop(this.nowMap);
   return false;
}

functions.afterJumpMap:
{
   var _loc4_;
   var _loc3_;
   if(nextEntry != undefined)
   {
      _loc4_ = this[nextEntry]._x;
      _loc3_ = this[nextEntry]._y;
      this.role._x = _loc4_;
      this.role._y = _loc3_;
      this.huanShou1._x = _loc4_ - 15;
      this.huanShou1._y = _loc3_ - 15;
      this.huanShou2._x = _loc4_ + 5;
      this.huanShou2._y = _loc3_ + 5;
      this.huanShou3._x = _loc4_ + 20;
      this.huanShou3._y = _loc3_ + 20;
   }
   this.nextMap = "";
   this.nextEntry = "";
   _global.ownMap = false;
   this.hideMonster();
   this.hideNPC();
   if(nowMap != "冰宫郊区")
   {
      this.冰柱._visible = false;
   }
   return true;
}

